const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;
const W=960,H=540,levelW=3640,gravity=.55;
const ui={overlay:document.getElementById('overlay'),title:document.getElementById('title'),subtitle:document.getElementById('subtitle'),eyebrow:document.getElementById('eyebrow'),features:document.getElementById('features'),note:document.getElementById('actionNote'),button:document.getElementById('startBtn'),hud:document.getElementById('hud'),shards:document.getElementById('shardCount'),hearts:document.getElementById('hearts'),toast:document.getElementById('toast')};
const platforms=[{x:0,y:476,w:620},{x:690,y:476,w:390},{x:1150,y:476,w:570},{x:1800,y:476,w:500},{x:2370,y:476,w:500},{x:2940,y:476,w:700},{x:260,y:390,w:150},{x:470,y:330,w:135},{x:790,y:385,w:150},{x:970,y:320,w:120},{x:1270,y:385,w:155},{x:1490,y:330,w:140},{x:1650,y:400,w:110},{x:1900,y:375,w:160},{x:2120,y:315,w:155},{x:2370,y:385,w:155},{x:2600,y:325,w:150},{x:2830,y:390,w:120},{x:3100,y:380,w:155},{x:3320,y:320,w:160}];
const shardSpots=[[300,355],[520,295],[845,350],[1010,285],[1325,350],[1540,295],[1945,340],[2170,280],[2415,350],[2645,290],[2865,355],[3145,345],[3370,285],[1750,430],[2320,430],[2910,430]];
let shards=shardSpots.map(([x,y],i)=>({x,y,got:false,phase:i*1.7}));
const enemies=[{x:385,y:0,min:335,max:565,dir:1},{x:840,y:0,min:740,max:990,dir:-1},{x:1390,y:0,min:1210,max:1660,dir:1},{x:2020,y:0,min:1860,max:2280,dir:-1},{x:2500,y:0,min:2390,max:2800,dir:1},{x:3210,y:0,min:3000,max:3550,dir:-1}].map((e,i)=>({...e,w:30,h:26,alive:true,speed:1.05+(i%2)*.25,phase:i*1.3}));
const player={x:70,y:420,w:24,h:36,vx:0,vy:0,face:1,onGround:false,health:3,attack:0,cool:0,invuln:0,spawn:70,checkpoint:70,anim:0};
const input={left:false,right:false,jump:false,attack:false};let camera=0,gameState='title',tick=0,score=0,gateActive=false,toastTimer=0;
function startGame(){if(gameState==='won')resetGame();gameState='playing';ui.overlay.classList.add('hidden');ui.hud.classList.add('visible');ui.button.blur();canvas.focus()}
function showPanel(kind){gameState=kind;ui.hud.classList.remove('visible');ui.overlay.classList.remove('hidden');if(kind==='dead'){ui.eyebrow.textContent='SEKTOR 07 · SINYAL TERPUTUS';ui.title.innerHTML='COBA<br><span>LAGI</span>';ui.subtitle.textContent='Bayangan terlalu kuat kali ini, Ren. Atur waktu seranganmu dan terus bergerak—kota masih menunggumu.';ui.features.innerHTML='<span class="tag"><i>TIP</i> Serangan Pulse mengalahkan musuh</span><span class="tag"><i>TIP</i> Shard memulihkan 1 hati</span>';ui.button.textContent='ULANGI PETUALANGAN  →';ui.note.innerHTML='Tekan R atau tombol untuk mencoba lagi';}
if(kind==='won'){ui.eyebrow.textContent='MISI SELESAI · NOX CITY MENYALA';ui.title.innerHTML='CAHAYA<br><span>KEMBALI</span>';ui.subtitle.textContent=`Ren berhasil menyalakan gerbang kota! Kamu mengumpulkan ${score} shard dan membersihkan ancaman bayangan.`;ui.features.innerHTML=`<span class="tag"><i>✦</i> ${String(score).padStart(2,'0')} SHARD TERKUMPUL</span><span class="tag"><i>✓</i> MISI TUNTAS</span>`;ui.button.textContent='MAIN LAGI  →';ui.note.innerHTML='Petualangan baru dimulai dari awal';}}
function resetGame(){player.x=70;player.y=420;player.vx=player.vy=0;player.health=3;player.invuln=0;player.checkpoint=70;score=0;shards.forEach(s=>s.got=false);enemies.forEach(e=>e.alive=true);gateActive=false;ui.shards.textContent='00';updateHearts()}
ui.button.addEventListener('click',startGame);
function updateHearts(){ui.hearts.textContent=Array.from({length:3},(_,i)=>i<player.health?'♥':'♡').join(' ')}
function setKey(code,on){if(code==='ArrowLeft'||code==='KeyA')input.left=on;if(code==='ArrowRight'||code==='KeyD')input.right=on;if(code==='Space'||code==='ArrowUp'||code==='KeyW')input.jump=on;if(code==='KeyX'||code==='KeyJ')input.attack=on;if(on&&code==='KeyR'&&gameState==='dead'){resetGame();startGame()}}
window.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','Space'].includes(e.code))e.preventDefault();if(!e.repeat)setKey(e.code,true);if(e.code==='Escape'&&gameState==='playing'){gameState='paused';ui.overlay.classList.remove('hidden');ui.hud.classList.remove('visible');ui.eyebrow.textContent='JEDA SEBENTAR';ui.title.innerHTML='TARIK<br><span>NAPAS</span>';ui.subtitle.textContent='Kota Nox bisa menunggu. Siap kembali ke misi?';ui.features.innerHTML='<span class="tag"><i>PAUSE</i> Progresmu tersimpan</span>';ui.button.textContent='LANJUTKAN  →';ui.note.innerHTML='Esc untuk menjeda atau lanjut';ui.button.onclick=()=>{ui.button.onclick=null;ui.button.addEventListener('click',startGame,{once:true});startGame()}}});
window.addEventListener('keyup',e=>setKey(e.code,false));window.addEventListener('blur',()=>Object.keys(input).forEach(k=>input[k]=false));
document.querySelectorAll('.mobile-controls button').forEach(btn=>{const key=btn.dataset.key,down=e=>{e.preventDefault();btn.classList.add('pressed');input[key==='jump'?'jump':key==='attack'?'attack':key]=true},up=e=>{e.preventDefault();btn.classList.remove('pressed');input[key==='jump'?'jump':key==='attack'?'attack':key]=false};btn.addEventListener('pointerdown',down);btn.addEventListener('pointerup',up);btn.addEventListener('pointercancel',up);btn.addEventListener('pointerleave',up)});
function floorAt(x,y,dy){for(const p of platforms){if(x+player.w>p.x&&x<p.x+p.w&&y+player.h<=p.y+2&&y+player.h+dy>=p.y)return p.y}return H+100}
function hurt(){if(player.invuln>0)return;player.health--;updateHearts();player.invuln=100;player.vy=-6;player.vx=-player.face*3;if(player.health<=0){setTimeout(()=>showPanel('dead'),450)}}
function doAttack(){if(player.cool<=0){player.attack=13;player.cool=25;for(const e of enemies){if(!e.alive)continue;const ex=e.x+e.w/2,px=player.x+player.w/2;if(Math.abs(ex-px)<57&&Math.abs((e.y+e.h)-(player.y+player.h))<48&&((ex-px)*player.face)>-9){e.alive=false;score++;ui.shards.textContent=String(score).padStart(2,'0')}}}}
function update(){if(gameState!=='playing')return;tick++;player.anim++;
const move=(input.right?1:0)-(input.left?1:0);player.vx+=(move*.62-player.vx)*.28;if(Math.abs(player.vx)<.08)player.vx=0;if(move)player.face=move;
if(input.jump&&player.onGround){player.vy=-10.8;player.onGround=false}if(input.attack){input.attack=false;doAttack()}if(player.cool>0)player.cool--;if(player.attack>0)player.attack--;if(player.invuln>0)player.invuln--;
player.vy=Math.min(player.vy+gravity,12);const oldY=player.y;player.x=Math.max(0,Math.min(levelW-player.w,player.x+player.vx));player.y+=player.vy;player.onGround=false;if(player.vy>=0){const fy=floorAt(player.x,oldY,player.vy);if(player.y+player.h>=fy){player.y=fy-player.h;player.vy=0;player.onGround=true}}
if(player.y>H+30){hurt();player.x=player.checkpoint;player.y=340;player.vy=0}
for(const e of enemies){if(!e.alive)continue;e.x+=e.dir*e.speed;if(e.x<e.min||e.x>e.max)e.dir*=-1;e.y=(platforms.filter(p=>e.x+e.w>p.x&&e.x<p.x+p.w).reduce((a,p)=>Math.min(a,p.y),H+100))-e.h;if(e.y>H)e.y=450;if(player.x<e.x+e.w&&player.x+player.w>e.x&&player.y<e.y+e.h&&player.y+player.h>e.y){if(player.vy>1&&player.y+player.h<e.y+e.h*.6){e.alive=false;player.vy=-7;score++;ui.shards.textContent=String(score).padStart(2,'0')}else hurt()}}
for(const s of shards){if(s.got)continue;if(Math.abs(player.x+12-s.x)<23&&Math.abs(player.y+18-s.y)<30){s.got=true;score++;player.health=Math.min(3,player.health+1);updateHearts();ui.shards.textContent=String(score).padStart(2,'0')}}
if(player.x>levelW-125){if(score>=6){showPanel('won')}else if(!gateActive){gateActive=true;showToast('GERBANG TERKUNCI · BUTUH 6 SHARD')}}
camera=Math.max(0,Math.min(levelW-W,player.x-W*.36));if(toastTimer>0){toastTimer--;if(toastTimer===0)ui.toast.classList.remove('show')}
}
function showToast(txt){ui.toast.textContent=txt;ui.toast.classList.add('show');toastTimer=150}

function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),w,h)}
function drawBackground(){const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#17152c');sky.addColorStop(.58,'#292043');sky.addColorStop(1,'#482b54');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
// distant moons and pixel stars
ctx.fillStyle='#efe4ff';ctx.globalAlpha=.7;ctx.fillRect(759,72,3,3);ctx.fillRect(220,108,2,2);ctx.fillRect(842,154,2,2);ctx.fillRect(94,71,2,2);ctx.globalAlpha=1;
ctx.fillStyle='#cbbce5';ctx.fillRect(745,94,34,2);ctx.fillRect(757,82,2,25);ctx.fillStyle='#e49dff';ctx.fillRect(757,92,3,3);
// far skyline
for(let i=0;i<22;i++){const base=i*67-(camera*.16%67),x=base-12;const bh=70+((i*37)%120);rect(x,H-64-bh,52,bh,'#211b38');rect(x+5,H-67-bh,42,5,'#342448');for(let wy=H-52-bh;wy<H-76;wy+=19)for(let wx=x+9;wx<x+43;wx+=15)if(((wx+wy+i)%3)!==0)rect(wx,wy,5,7,'#705076')}
// mid skyline
for(let i=0;i<13;i++){const x=i*112-(camera*.35%112)-10,bh=95+((i*51)%105);rect(x,H-60-bh,84,bh,'#29203d');rect(x+9,H-66-bh,66,8,'#3b2b50');rect(x+17,H-90-bh,3,24,'#514063');for(let wy=H-48-bh;wy<H-76;wy+=22)for(let wx=x+13;wx<x+73;wx+=20)if((i+wx+wy)%2)rect(wx,wy,6,9,'#a64caa')}
// atmospheric horizon glow
const glow=ctx.createLinearGradient(0,330,0,500);glow.addColorStop(0,'#e765bf00');glow.addColorStop(1,'#d94ca32b');ctx.fillStyle=glow;ctx.fillRect(0,330,W,170);
// floating scanlines subtle
ctx.fillStyle='#d3bdff08';for(let y=0;y<H;y+=4)ctx.fillRect(0,y,W,1)
}
function drawPlatforms(){for(const p of platforms){const x=Math.round(p.x-camera);if(x+p.w<0||x>W)continue;rect(x,p.y,p.w,H-p.y+80,'#211c2c');rect(x,p.y,p.w,7,'#6e5475');rect(x,p.y+7,p.w,H-p.y+60,'#33283c');rect(x,p.y+7,p.w,2,'#ac7190');for(let n=0;n<p.w;n+=34){rect(x+n+3,p.y+16,16,2,'#594155');rect(x+n+18,p.y+34,8,2,'#51404f')}rect(x,p.y+8,4,12,'#cf69bb');rect(x+p.w-4,p.y+8,4,12,'#cf69bb');}
// electric gap hazard glow
for(const gx of [620,1080,1720,2300,2870]){const x=gx-camera;if(x<-20||x>W+20)continue;ctx.globalAlpha=.45+.25*Math.sin(tick*.12+gx);rect(x,468,68,8,'#ff4f9d');rect(x+8,462,52,4,'#ff8bcd');ctx.globalAlpha=1;for(let i=0;i<4;i++){const sx=x+5+i*17;rect(sx,470+Math.sin(tick*.2+i)*3,5,3,'#fff0bb')}}}
function drawShard(s){if(s.got)return;const x=s.x-camera,y=s.y+Math.sin(tick*.07+s.phase)*5;ctx.save();ctx.translate(Math.round(x),Math.round(y));ctx.rotate(Math.sin(tick*.045+s.phase)*.18);rect(-3,-10,6,20,'#fff2a1');rect(-7,-6,14,12,'#ffd45d');rect(-3,-13,6,4,'#fff9d8');rect(-2,-5,4,9,'#fff1a7');rect(-10,-2,3,4,'#ff9e59');rect(7,2,3,4,'#ff9e59');ctx.restore();ctx.globalAlpha=.2;rect(x-9,y-9,18,18,'#ffdf67');ctx.globalAlpha=1}
function drawEnemy(e){if(!e.alive)return;const x=Math.round(e.x-camera),y=Math.round(e.y+Math.sin(tick*.14+e.phase)*2);ctx.fillStyle='#09071377';ctx.fillRect(x-4,y+e.h-1,38,5);rect(x+3,y+8,24,16,'#552b70');rect(x+7,y+3,16,8,'#743b92');rect(x+1,y+15,6,8,'#763995');rect(x+24,y+15,6,8,'#763995');rect(x+8,y+10,5,4,'#ff536e');rect(x+19,y+10,5,4,'#ff536e');rect(x+9,y+10,2,2,'#fff');rect(x+20,y+10,2,2,'#fff');rect(x+11,y+25,3,3,'#ce73e6');rect(x+20,y+25,3,3,'#ce73e6');}
function drawGate(){const x=levelW-104-camera;if(x<-100||x>W+100)return;const active=score>=6;ctx.globalAlpha=active?.9:.5;rect(x,365,12,112,'#564364');rect(x+72,365,12,112,'#564364');rect(x-5,358,94,10,'#9474a5');rect(x+12,380,60,95,active?'#ba53ed':'#392840');rect(x+18,386,48,83,active?'#73f4e3':'#6e435f');if(active){ctx.globalAlpha=.4+.2*Math.sin(tick*.1);rect(x+23,390,38,72,'#e1a4ff');ctx.globalAlpha=.9;rect(x+31,403,22,44,'#e2cbff');rect(x+37,393,10,9,'#fff')}else{rect(x+32,407,20,20,'#f1bd57');rect(x+38,412,8,12,'#432a3d')}ctx.globalAlpha=1;}
function drawPlayer(){if(player.invuln>0&&Math.floor(tick/5)%2===0)return;const x=Math.round(player.x-camera),y=Math.round(player.y),run=Math.abs(player.vx)>.3&&player.onGround,step=run?Math.floor(player.anim/5)%2:0;
// shadow
ctx.fillStyle='#08061088';ctx.fillRect(x-5,y+player.h-1,34,5);
// attack arc
if(player.attack>0){const ax=x+(player.face===1?20:-38),ay=y+6;ctx.globalAlpha=.82;rect(ax,ay,18,4,'#f7f5ff');rect(ax+2,ay+4,22,4,'#c979ff');rect(ax+(player.face===1?7:-7),ay-5,4,18,'#77f8ef');rect(ax+(player.face===1?15:-15),ay+8,8,3,'#ffdf71');ctx.globalAlpha=1}
ctx.save();if(player.face<0){ctx.translate(x*2+player.w,0);ctx.scale(-1,1)}
// boots and legs
const leg=run?step:0;rect(x+4,y+27,7,6,'#16111f');rect(x+5+leg,y+31,7,4,'#080810');rect(x+14,y+27,7,6,'#16111f');rect(x+14-leg,y+31,7,4,'#080810');rect(x+3+leg,y+34,10,3,'#0a0910');rect(x+13-leg,y+34,10,3,'#0a0910');rect(x+4+leg,y+33,5,1,'#a446ca');rect(x+16-leg,y+33,5,1,'#a446ca');
// torso dark jacket
rect(x+5,y+15,15,13,'#14111c');rect(x+3,y+18,4,9,'#1c1725');rect(x+19,y+17,4,9,'#201827');rect(x+6,y+16,13,2,'#32233a');rect(x+11,y+17,3,9,'#5de4dc');rect(x+12,y+19,2,3,'#f5e4ff');rect(x+6,y+25,13,2,'#08080e');
// neck and face
rect(x+10,y+11,7,5,'#d99582');rect(x+6,y+5,14,10,'#e6a18a');rect(x+5,y+8,2,5,'#be796e');rect(x+19,y+8,2,4,'#f0b29a');rect(x+9,y+10,3,2,'#252137');rect(x+16,y+10,3,2,'#252137');rect(x+12,y+13,5,1,'#874d61');
// black anime hair with fringe
rect(x+4,y+2,17,5,'#100e18');rect(x+6,y,12,4,'#171420');rect(x+3,y+4,5,5,'#12101b');rect(x+7,y+5,4,4,'#100e18');rect(x+10,y+5,4,6,'#171420');rect(x+14,y+5,4,4,'#0c0b13');rect(x+18,y+3,4,6,'#12101b');rect(x+7,y+1,3,2,'#373044');rect(x+15,y+2,3,2,'#2e293b');
// belt + arm/hand
rect(x+7,y+27,11,2,'#393045');rect(x+14,y+27,3,2,'#f0bb58');rect(x+1,y+20,4,7,'#12101a');rect(x+1,y+26,5,3,'#d99380');rect(x+20,y+19,4,7,'#15111c');rect(x+21,y+25,5,4,'#d99380');ctx.restore();
}

function drawForeground(){// foreground silhouettes and neon floor markers
for(let i=0;i<18;i++){const x=i*225-(camera*.75%225);if(x<-20||x>W)continue;rect(x,461,2,15,'#ed5aa1');rect(x-4,462,10,2,'#ed5aa1');rect(x-2,458,6,2,'#ffb0dd')}
}
function render(){ctx.clearRect(0,0,W,H);drawBackground();drawGate();drawPlatforms();for(const s of shards)drawShard(s);for(const e of enemies)drawEnemy(e);drawPlayer();drawForeground();
// vignette and subtle pixel frame
const v=ctx.createRadialGradient(W/2,H/2,120,W/2,H/2,590);v.addColorStop(.65,'#100a1900');v.addColorStop(1,'#08061199');ctx.fillStyle=v;ctx.fillRect(0,0,W,H);
}
function loop(){update();render();requestAnimationFrame(loop)}
loop();
</script>
</body>
</html>

