function floorAt(x,y,dy){for(const p of platforms)if(x+player.w>p.x&&x<p.x+p.w&&y+player.h<=p.y+2&&y+player.h+dy>=p.y)return p.y;return H+100}
function showToast(txt){ui.toast.textContent=txt;ui.toast.classList.add('show');toastTimer=150}
function hurt(){if(player.invuln>0)return;player.health--;updateHearts();player.invuln=100;player.vy=-6;player.vx=-player.face*3;if(player.health<=0)setTimeout(()=>showPanel('dead'),450)}
function doAttack(){if(player.cool>0)return;player.attack=13;player.cool=25;for(const e of enemies){if(!e.alive)continue;const dx=e.x+e.w/2-(player.x+player.w/2);if(Math.abs(dx)<57&&Math.abs(e.y+e.h-player.y-player.h)<48&&dx*player.face>-9){e.alive=false;score++;ui.shards.textContent=String(score).padStart(2,'0')}}}
function update(){if(gameState!=='playing')return;tick++;player.anim++;const move=(input.right?1:0)-(input.left?1:0);player.vx+=(move*.62-player.vx)*.28;if(Math.abs(player.vx)<.08)player.vx=0;if(move)player.face=move;
if(input.jump&&player.onGround){player.vy=-10.8;player.onGround=false}if(input.attack){input.attack=false;doAttack()}if(player.cool>0)player.cool--;if(player.attack>0)player.attack--;if(player.invuln>0)player.invuln--;
player.vy=Math.min(player.vy+gravity,12);const oldY=player.y;player.x=Math.max(0,Math.min(levelW-player.w,player.x+player.vx));player.y+=player.vy;player.onGround=false;if(player.vy>=0){const fy=floorAt(player.x,oldY,player.vy);if(player.y+player.h>=fy){player.y=fy-player.h;player.vy=0;player.onGround=true}}
if(player.y>H+30){hurt();player.x=player.checkpoint;player.y=340;player.vy=0}
for(const e of enemies){if(!e.alive)continue;e.x+=e.dir*e.speed;if(e.x<e.min||e.x>e.max)e.dir*=-1;e.y=platforms.filter(p=>e.x+e.w>p.x&&e.x<p.x+p.w).reduce((a,p)=>Math.min(a,p.y),H+100)-e.h;if(e.y>H)e.y=450;if(player.x<e.x+e.w&&player.x+player.w>e.x&&player.y<e.y+e.h&&player.y+player.h>e.y){if(player.vy>1&&player.y+player.h<e.y+e.h*.6){e.alive=false;player.vy=-7;score++;ui.shards.textContent=String(score).padStart(2,'0')}else hurt()}}
for(const s of shards){if(s.got)continue;if(Math.abs(player.x+12-s.x)<23&&Math.abs(player.y+18-s.y)<30){s.got=true;score++;player.health=Math.min(3,player.health+1);updateHearts();ui.shards.textContent=String(score).padStart(2,'0')}}
for(const cp of [1180,2370])if(player.x>cp&&player.checkpoint<cp){player.checkpoint=cp;showToast('CHECKPOINT AKTIF')}
if(player.x>levelW-125){if(score>=6)showPanel('won');else if(!gateActive){gateActive=true;showToast('GERBANG TERKUNCI · BUTUH 6 SHARD')}}
camera=Math.max(0,Math.min(levelW-W,player.x-W*.36));if(toastTimer>0&&--toastTimer===0)ui.toast.classList.remove('show')}
//CHUNK3

